<script setup lang="ts">import {Head,Link} from '@inertiajs/vue3';import PageHeader from '@/Components/Shared/PageHeader.vue';import {Button} from '@/components/ui/button';defineProps<{campaigns:any[]}>();const money=(v:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(v/100);</script><template><Head title="Advertising Campaigns"/><div class="space-y-6 p-6"><div class="flex justify-between"><PageHeader title="Advertising Campaigns" description="Manage paid sponsorship and advertising campaigns separately from internal marketing promotions."/><Link href="/admin/ad-campaigns/create"><Button>Create Campaign</Button></Link></div><div class="overflow-hidden rounded-xl border"><table class="w-full text-sm"><thead class="bg-muted/50"><tr><th class="p-3 text-left">Campaign</th><th>Advertiser</th><th>Status</th><th>Placements</th><th>Contract</th><th></th></tr></thead><tbody><tr v-for="c in campaigns" :key="c.id" class="border-t"><td class="p-3"><Link :href="`/admin/ad-campaigns/${c.id}`" class="font-medium hover:underline">{{c.name}}</Link><div class="text-muted-foreground">{{c.public_code}}</div></td><td>{{c.advertiser.name}}</td><td>{{c.status}}</td><td>{{c.placements.length}}</td><td>{{money(c.contract_value_cents)}}</td><td class="p-3 text-right"><Link :href="`/admin/ad-campaigns/${c.id}/edit`"><Button size="sm" variant="outline">Edit</Button></Link></td></tr></tbody></table></div></div></template>